  function transparencyModal(){
    const api=intelligence();const snapshot=api.getSystemSnapshot();let memory=null;try{memory=api.getMemorySnapshot()}catch{}
    const capabilities=snapshot.capabilities||[],tiers=snapshot.modelTiers||[],sources=snapshot.sourceContracts||[];
    const body=`<p class="luv-ai-transparency-intro">Luvia verbindet nur Reiseinformationen, die für deinen Wunsch freigegeben und erforderlich sind. Fakten stammen aus den jeweils genannten Quellen; jede Änderung bestätigst du selbst.</p><div class="luv-ai-transparency-metrics"><article><b>${capabilities.length}</b><span>aktive Hilfen</span></article><article><b>${sources.length}</b><span>verbundene Reisebereiche</span></article><article><b>${memory?.summary?.byStatus?.inferred||0}</b><span>offene Lernvorschläge</span></article></div><section class="luv-ai-transparency-section"><h3>Wie Luvia antwortet</h3><div class="luv-ai-transparency-list">${tiers.map(tier=>`<article><strong>${esc(tier.alias)}</strong><span>${esc(tier.purpose)}</span></article>`).join('')}</div></section><section class="luv-ai-transparency-section"><h3>Was Luvia gerade kann</h3><div class="luv-ai-capability-grid">${capabilities.map(capability=>`<article><strong>${esc(capability.description||capability.id)}</strong></article>`).join('')}</div></section><section class="luv-ai-transparency-section"><h3>Woher die Informationen kommen</h3><p>Reise, Orte, Tagesplan, Buchungen, Vorlieben und Erinnerungen bleiben getrennt geschützt. Luvia verbindet sie nur für deinen aktuellen Wunsch.</p></section><div class="luv-ai-policy-callout"><b>Du entscheidest.</b><span>Bevor Luvia etwas hinzufügt, ändert, storniert oder löscht, siehst du die Folgen und bestätigst ausdrücklich.</span></div><div class="luv-ai-proposal-actions"><button type="button" data-ai-close>Verstanden</button></div>`;
    return modalShell({name:'intelligence.transparency',kicker:'Intelligence Transparency',title:'So denkt Luvia',className:'luv-ai-transparency',initialFocus:'[data-ai-close]',body});
  }
